#!/usr/bin/env python3
from pathlib import Path
import base64

manager = Path("components/cosmetics/player-cosmetics-manager.tsx")
context = Path("components/portal/portal-context-panel.tsx")
navigator = Path("components/cosmetics/player-cosmetics-context-panel.tsx")

for path in (manager, context):
    if not path.exists():
        raise SystemExit(f"PATCH STOPPED: missing {path}. Run from the repository root.")

manager_text = manager.read_text(encoding="utf-8")
context_text = context.read_text(encoding="utf-8")

if 'const [category, setCategory]' not in manager_text:
    raise SystemExit("PATCH STOPPED: PlayerCosmeticsManager no longer matches the expected current structure.")

if navigator.exists():
    raise SystemExit("PATCH STOPPED: player-cosmetics-context-panel.tsx already exists.")

manager.write_text(
    base64.b64decode("").decode("utf-8"),
    encoding="utf-8",
    newline="\n",
)

navigator.write_text(
    base64.b64decode("").decode("utf-8"),
    encoding="utf-8",
    newline="\n",
)

import_anchor = 'import { SanctionContextPanel } from "@/components/sanctions/sanction-context-panel";\n'
import_replacement = (
    'import { SanctionContextPanel } from "@/components/sanctions/sanction-context-panel";\n'
    'import {\n'
    '  PlayerCosmeticsContextPanel,\n'
    '} from "@/components/cosmetics/player-cosmetics-context-panel";\n'
)

if context_text.count(import_anchor) != 1:
    raise SystemExit("PATCH STOPPED: portal context import anchor not found exactly once.")

context_text = context_text.replace(import_anchor, import_replacement, 1)

route_anchor = 'if (pathname === "/cosmetics") {\n  return <CosmeticsContextPanel />;\n}\n'
route_replacement = 'if (pathname === "/cosmetics") {\n  return <PlayerCosmeticsContextPanel />;\n}\n'

if context_text.count(route_anchor) != 1:
    raise SystemExit("PATCH STOPPED: /cosmetics context route anchor not found exactly once.")

context_text = context_text.replace(route_anchor, route_replacement, 1)

context.write_text(
    context_text,
    encoding="utf-8",
    newline="\n",
)

print("✓ /cosmetics is now one grouped catalogue.")
print("✓ Main category selector/switch workflow removed.")
print("✓ All owned cosmetics are visible on one page, grouped by type.")
print("✓ Equipped state + Equip/Unequip live directly on each card.")
print("✓ Context bar searches by cosmetic type and/or cosmetic name.")
print("✓ Type selector narrows context navigation only; it does not hide page content.")
print("✓ Search/type results jump to and briefly highlight the selected section/card.")
print("✓ No extra Supabase query or poller was added.")
print("\nPATCH COMPLETE")
print("\nRun: npm run build")
